from pathlib import Path
import re,json,html
p=Path(__file__).parent/'dist'; old=(p/'index.html').read_text();basecss=(p/'style.css').read_text()
head=old.split('<main>')[0];foot=old.split('</main>')[1];nav=[('index.html','Home'),('research.html','Research'),('publications.html','Publications'),('team.html','Team'),('news.html','News'),('resources.html','Resources'),('director.html','Director')]
head=re.sub(r'<div class="links" id="navigation">.*?</div>', '<div class="links" id="navigation">'+''.join(f'<a href="{u}">{n}</a>' for u,n in nav)+'</div>',head)
head=head.replace('SHIELD Lab</title>','SHIELD Lab</title>')
def page(name,body,title):
 h=head.replace('<title>SHIELD Lab</title>',f'<title>{title} | SHIELD Lab</title>').replace(f'href="{name}">{title}</a>',f'href="{name}" aria-current="page">{title}</a>')
 (p/name).write_text(h+'<main>'+body+'</main>'+foot)
def intro(label,title,desc):return f'<section class="page-intro"><div class="eyebrow">{label}</div><h1>{title}</h1><p>{desc}</p></section>'
def sect(title,content):return f'<section class="section"><h2>{title}</h2>{content}</section>'
news=[('2026','EMNLP','Edits in the Wild','A multilingual benchmark of on-device image editing across consumer platforms.','https://shieldlab.github.io/On-Device-AI-Edit-Forensics/'),('2026','ACL · Industry','No Innocence in Styling','Research on the privacy protection and security risks of consumer generative AI writing assistants.','https://farhan1503001.github.io/#publications'),('2025','Preprint','Sponge Attacks on Sensing AI','Investigating energy–latency vulnerabilities and model-pruning defenses.','https://arxiv.org/abs/2505.06454')]
def newsrows():return ''.join(f'<article class="news"><time>{yr}<br><span class="tag">{venue}</span></time><div><h3><a href="{url}">{title} ↗</a></h3><p>{desc}</p></div></article>' for yr,venue,title,desc,url in news)
page('news.html',intro('Lab updates','News & highlights','Research milestones and recent work from SHIELD Lab.')+sect('Research highlights',newsrows())+'<p class="editor-note">Preview archive: these entries reflect verified research records, not exact announcement dates. Older lab news can be added after review.</p>','News')
people=[('Syed Mhamudul Hasan','PhD student','Security, privacy & sustainable AI',1,None),('Malithi Wanniarachchi Kankanamge','PhD student','Wearable AI & sensor-language learning',2,'https://malithi-gif.github.io/Portfolio-Malithi/'),('Mohd. Farhan Israk Soumik','MS student','Generative AI forensics & privacy',3,'https://farhan1503001.github.io/'),('Bhargav Vaddepally','MS student','AI software engineering',4,None)]
def person(n,role,interest,img,url):return f'<article class="person"><img class="headshot" src="assets/team-{img}.jpg" alt="{n}"><div class="person-info"><span class="tag">{role}</span><h3>{n}</h3><p>{interest}</p>'+ (f'<a class="text-link" href="{url}">Personal website ↗</a>' if url else '<span class="small muted">Personal website not yet linked</span>')+'</div></article>'
team=intro('Our people','Meet the lab','A community studying security, privacy, and trust in intelligent systems.')+sect('Director','<a class="director-card" href="director.html"><img src="assets/director.jpg" alt="Abdur Rahman Bin Shahid"><div><span class="tag">Assistant Professor · School of Computing</span><h3>Abdur Rahman Bin Shahid</h3><p>Director, SHIELD Lab</p><span class="text-link">Director profile →</span></div></a>')+sect('Graduate researchers','<div class="people">'+''.join(person(*x) for x in people)+'</div>')+sect('Undergraduate researchers','<div class="people">'+person('Nadia D. Lafontant','Undergraduate · REACH','Small language model vulnerabilities',5,None)+'</div>')+sect('Alumni','<div class="alumni"><article><h3>Aman Singh Thakur</h3><p>MS project · Spring 2024<br>Wearable sensor data collection for adversarial ML.</p><a class="text-link" href="https://www.shieldlab.info/theses-and-projects">Project summary ↗</a></article><article><h3>Satwik Boyina</h3><p>MS project · Spring 2024<br>Hexoskin data integration for activity recognition.</p><a class="text-link" href="https://www.shieldlab.info/theses-and-projects">Project summary ↗</a></article></div><p class="editor-note">Alumni portraits and personal websites are not available in the current lab records. No substitute portraits have been used.</p>')
page('team.html',team,'Team')
projects=[
('systems','Secure and Sustainable AI Systems and Infrastructure','How can security and efficiency be evaluated together?',[
 ('Resource-aware adversarial resilience','Investigating how adversarial activity affects the energy use and latency of sensing AI, and how defenses change those costs.','Measure attacks and defenses jointly across predictive utility, energy, and latency.','Connect robustness to operational cost rather than evaluating accuracy alone.','Published and preprint foundations','https://arxiv.org/abs/2505.06454','Sponge Attacks on Sensing AI'),
 ('Sustainable machine learning','Studying methods for quantifying the environmental cost of machine learning and adversarial training.','Compare measurement choices and the resource implications of secure ML.','Make the tradeoffs between protection and environmental cost explicit.','Existing research','publications.html#journals','Selected sustainability publications'),
 ('AI infrastructure and agent systems','An emerging direction exploring resource-aware AI deployment, including future questions about data-center-scale systems and interacting agents.','Develop a research agenda for evaluating security, resource use, and evidence flow.','Study interactions between system-scale constraints and trustworthy AI behavior.','Emerging direction · not an established deployment',None,None)]),
('security','AI Security, Privacy and Resilience','What makes intelligent systems vulnerable, and how can we protect them?',[
 ('Wearable AI across the lifecycle','Studying attacks and defenses in sensor-based activity recognition, including data manipulation and privacy risks.','Evaluate resilient learning and trustworthy interpretations of wearable signals.','Connect sensor structure, learning behavior, and security across collection, training, and use.','Existing research','https://arxiv.org/abs/2511.02894','Adaptive and Robust Data Poisoning Detection and Sanitization'),
 ('Privacy in human–AI interaction','Examining how consumer AI writing and editing tools change the exposure of personal information.','Measure both protective capabilities and security risks in everyday AI tools.','Treat consumer tools as both possible privacy defenses and sources of new vulnerabilities.','Existing research','publications.html#conferences','No Innocence in Styling'),
 ('Language models for cyber-physical systems','Investigating language-model integration with sensing, healthcare, and distributed decision-making.','Explore useful interaction while considering privacy, security, and resource constraints.','Connect language-based reasoning with the requirements of physical environments.','Existing research','publications.html#conferences','Selected CPS publications')]),
('forensics','Digital Forensics and AI Provenance','What evidence can we recover about digital content and AI interactions?',[
 ('On-device generative image-edit forensics','ConsumerGenEdit studies images edited using native consumer tools across devices and platforms.','Detect and localize edits, evaluate multilingual descriptions, and study compression effects.','Ground forensic evaluation in real consumer workflows rather than only fully synthetic images.','EMNLP 2026','https://shieldlab.github.io/On-Device-AI-Edit-Forensics/','Edits in the Wild'),
 ('AI application forensics','Investigating artifacts left by the ChatGPT Windows application.','Identify and characterize digital traces relevant to forensic examination.','Extend application-forensic analysis to emerging AI interfaces.','Preprint','https://arxiv.org/abs/2505.23938','Digital Forensic Investigation of the ChatGPT Windows Application')])]
research=intro('Research agenda','Security. Sustainability.<br>Evidence.','Three connected pillars bring together established projects and clearly identified emerging directions.')+'<div class="jump-links">'+''.join(f'<a href="#{id}">{i+1:02d} {title}</a>' for i,(id,title,_,_) in enumerate(projects))+'</div>'
for id,title,q,items in projects:
 research+=f'<section class="section" id="{id}"><span class="eyebrow">Research pillar</span><h2>{title}</h2><p class="lead">{q}</p>'
 for title,desc,goal,merit,status,url,pub in items:
  research+=f'<article class="project-detail"><div><span class="tag">{status}</span><h3>{title}</h3><p>{desc}</p></div><div><h4>Goals</h4><p>{goal}</p><h4>Intellectual merit</h4><p>{merit}</p><h4>Selected publications</h4>'+(f'<a class="text-link" href="{url}">{pub} ↗</a>' if url else '<p>No project-specific publication listed for this emerging direction.</p>')+'</div></article>'
 research+='</section>'
research+='<p class="editor-note">Research descriptions are editorial summaries for this preview. Goals describe research intent, not guaranteed outcomes. Emerging agent and data-center directions are not presented as completed projects or funded infrastructure.</p>'
page('research.html',research,'Research')
resources=[('Compute & edge platforms',['Alienware workstation','Dell XPS laptops','Edge TPU device','NVIDIA Jetson Nano'],[0,2,1,9]),('Wearable & immersive sensing',['Hexoskin Pro Kit','Multimodal AI glasses','Meta Quest 3'],[6,7,8]),('Mobile & connected systems',['Android phones, tablet & iPad','IoT devices','Robot car kit'],[3,4,5])]
r=intro('Infrastructure & open materials','Resources','Platforms and materials that support experimental research in secure and trustworthy AI.')
