r+=sect('Campus-wide resources','<div class="grid"><article><h3>School of Computing</h3><p>GPU servers and research labs listed among campus computing resources.</p><a class="text-link" href="https://soc.siu.edu/">School of Computing ↗</a></article><article><h3>High-performance computing</h3><p>The current lab resource page lists Maxwell and BigDawg among SIU facilities. Access and availability are subject to campus arrangements.</p></article><article><h3>Virtual expression</h3><p>Interdisciplinary facilities and research at the Center for Virtual Expression.</p><a class="text-link" href="https://cvex.ai/">CVEX ↗</a></article></div>')+sect('Code & datasets','<div class="grid"><article><h3>Lab code</h3><a class="text-link" href="https://github.com/shieldlab">GitHub repositories ↗</a></article><article><h3>ConsumerGenEdit</h3><a class="text-link" href="https://shieldlab.github.io/On-Device-AI-Edit-Forensics/dataset.html">Dataset information & terms ↗</a></article><article><h3>Project materials</h3><a class="text-link" href="https://shieldlab.github.io/On-Device-AI-Edit-Forensics/">Image-edit forensics ↗</a></article></div>')+'<p class="editor-note">Equipment inventory adapted from the current SHIELD website. This does not imply unrestricted access, current reservation availability, or ownership of campus-wide facilities.</p>'
page('resources.html',r,'Resources')
# Keep director content, update global navigation.
d=(p/'director.html').read_text().split('<main>')[1].split('</main>')[0].replace('index.html#people','team.html').replace('index.html#publications','publications.html');page('director.html',d,'Director')
# Homepage remains compact, with full pages behind navigation.
home=old.split('<main>')[1].split('</main>')[0];home=re.sub(r'<section class="section" id="news">.*?</section>','<section class="section" id="news"><div class="section-heading"><h2>Latest news</h2><a class="text-link" href="news.html">All news →</a></div>'+newsrows()+'</section>',home,flags=re.S)
home=re.sub(r'<section class="section" id="research">.*?</section>','<section class="section" id="research"><div class="section-heading"><h2>Research pillars</h2><a class="text-link" href="research.html">Explore projects →</a></div><div class="grid">'+''.join(f'<a class="area" href="research.html#{id}"><span class="number">0{i+1}</span><h3>{title}</h3><p>{q}</p><span class="text-link">Projects & publications →</span></a>' for i,(id,title,q,_) in enumerate(projects))+'</div></section>',home,flags=re.S)
home=re.sub(r'<section class="section" id="people">.*?</section>','<section class="section" id="people"><div class="section-heading"><h2>The people behind SHIELD</h2><a class="text-link" href="team.html">Meet the team →</a></div><div class="people">'+''.join(person(*x) for x in people[:3])+'</div></section>',home,flags=re.S)
home=home.replace('https://www.shieldlab.info/publications','publications.html');page('index.html',home,'Home')
(p/'style.css').write_text(basecss+'''\n.page-intro{padding:65px 0 45px;max-width:850px}.page-intro h1{font-size:clamp(40px,5vw,60px)}.page-intro p,.lead{font-size:19px}.news h3{font-size:18px;letter-spacing:-.02em;margin:0 0 5px}.person{padding:0;overflow:hidden}.headshot{width:100%;height:245px;object-fit:cover;object-position:center 20%}.person-info{padding:22px}.section>h2{margin-bottom:30px}.alumni{display:grid;grid-template-columns:1fr 1fr;gap:30px}.alumni article{border-top:2px solid #70223b}.editor-note{font-size:13px;padding:16px;background:#faf8f9;border-left:2px solid #d9c4cc;margin-top:30px}.muted{color:#777}.project-detail{display:grid;grid-template-columns:1fr 1fr;gap:50px;padding:30px 0;border-top:1px solid #ece7e9}.project-detail h3{font-size:27px}.project-detail h4{margin:0;color:#70223b;font-size:13px;text-transform:uppercase;letter-spacing:.7px}.project-detail p{margin-top:7px}.jump-links{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:25px}.jump-links a{border:1px solid #e3d6db;padding:10px 16px;border-radius:4px;font-size:13px}.equipment-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.equipment{border:1px solid #e7e1e4;border-radius:5px;overflow:hidden}.equipment img{height:185px;width:100%;object-fit:contain;background:#fafafa;padding:14px}.equipment h3{font-size:18px;padding:0 20px 12px}.pub-search{width:100%;font:inherit;border:1px solid #d8c7ce;padding:12px 16px;border-radius:4px;margin-bottom:15px}.pub[hidden]{display:none}.links{gap:18px} .pub h3{overflow-wrap:anywhere}@media(max-width:760px){.equipment-grid,.project-detail,.alumni{grid-template-columns:1fr}.headshot{height:300px}.project-detail{gap:15px}.page-intro{padding:40px 0 30px}.links{gap:16px}.equipment img{height:210px}}''')
